import{_ as a,o as i,c as t,ag as e}from"./chunks/framework.C9sp7nFj.js";const u=JSON.parse('{"title":"GetAxisTorque 获取关节力矩","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/GetAxisTorque.md","filePath":"3. 指令/5. 设置指令/GetAxisTorque.md","lastUpdated":1778862643000}'),n={name:"3. 指令/5. 设置指令/GetAxisTorque.md"};function r(l,s,h,p,d,o){return i(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="getaxistorque-获取关节力矩" tabindex="-1">GetAxisTorque 获取关节力矩 <a class="header-anchor" href="#getaxistorque-获取关节力矩" aria-label="Permalink to &quot;GetAxisTorque 获取关节力矩&quot;">​</a></h1><p>该指令用于实时获取机器人各关节轴的力矩数据。通过监控电机在运行过程中的受力情况，用户可以实现诸如负载检测、接触判断或过程数据记录等高级逻辑控制。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>GetAxisTorque(AxisID, TorType, Res) GetAxisTorque(轴号, 力矩类型, 返回值)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>AxisID (轴号)</td><td>int</td><td>指定要获取力矩值的目标轴号（如 1 代表 1 轴）。</td><td></td></tr><tr><td>TorType (力矩类型)</td><td>enum</td><td>获取的力矩值类型。</td><td></td></tr><tr><td>Res 力矩返回值（Torque value）</td><td>INT 变量</td><td>返回的目标轴力矩值。</td><td></td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>机器人在运动或静止时，控制系统会根据伺服驱动器反馈的电流值，结合电机力矩常数计算出当前各关节的实际力矩。<code>GetAxisTorque</code> 指令允许用户从系统寄存器中提取这些实时变化的动力学数据，并将其存入用户定义的整型变量中。</p><hr><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 获取 2 轴当前的力矩百分比，并将结果存入变量 INT1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GetAxisTorque</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Percent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, INT1)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 如果 2 轴力矩超过 80%，执行安全处理逻辑</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IF</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (INT1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 80</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">THEN</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    SetRtWarning</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Axis 2 Torque High&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80001</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ENDIF</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><hr><h2 id="执行结果" tabindex="-1">执行结果 <a class="header-anchor" href="#执行结果" aria-label="Permalink to &quot;执行结果&quot;">​</a></h2><p>指令执行后，变量 <code>Res</code> 会立即更新为目标轴当前的实时力矩。该值是一个动态数值，会随着机器人的姿态变化、加速度改变以及外部阻力的大小而实时波动。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>力控辅助/碰撞预警</strong>：在没有配置专业碰撞参数时，通过循环检测关节力矩，实现自定义的软碰撞停机逻辑。</li><li><strong>工件状态判定</strong>：在抓取任务中，通过对比抓取前后关节力矩的变化，判断是否成功抓取到工件（掉料检测）。</li><li><strong>设备健康监控</strong>：定期记录特定动作下的力矩值，如果力矩随时间逐渐增大，可能预示着机械传动部分的润滑不良或硬件磨损。</li></ul>`,19)])])}const c=a(n,[["render",r]]);export{u as __pageData,c as default};
